  const cards = [...classCards, ...drugCards];
  const canonicalDrugKeys = new Set(drugCards.map((card) => normalize(card.generic || card.name)));
  const canonicalDrugAliasKeys = new Set(drugCards.flatMap((card) => [
    card.name,
    card.generic,
    ...(card.aliases || []),
    ...(card.brandExamples || [])
  ]).map(normalize).filter(Boolean));
  const curatedAliasOwner = new Map();
  cards.forEach((card) => {
    const owner = normalize(card.generic || card.name || card.displayName);
    [card.name, card.generic, ...(card.aliases || []), ...(card.brandExamples || [])]
      .map(normalize).filter(Boolean).forEach((alias) => curatedAliasOwner.set(alias, owner));
  });
  const map = new Map();
  db.drugs.forEach((drug) => {
    const key = normalize(drug.generic || drug.name || drug.displayName);
    if (canonicalDrugAliasKeys.has(key) && !canonicalDrugKeys.has(key)) return;
    if (key && !map.has(key)) map.set(key, drug);
  });

  cards.forEach((card) => {
    const key = normalize(card.generic || card.name || card.displayName);
    const existing = map.get(key) || {};
    const unclaimedExistingAliases = (existing.aliases || []).filter((alias) => {
      const owner = curatedAliasOwner.get(normalize(alias));
      return !owner || owner === key;
    });
    const unclaimedExistingBrands = (existing.brandExamples || []).filter((brand) => {
      const owner = curatedAliasOwner.get(normalize(brand));
      return !owner || owner === key;
    });
    map.set(key, {
      ...existing,
      ...card,
      generic: key,
      displayName: card.displayName || card.name,
      classPathway: Array.isArray(card.classPathway) && card.classPathway.length ? card.classPathway : [card.class],
      aliases: Array.from(new Set([...(card.aliases || []), ...unclaimedExistingAliases])),
      brandExamples: Array.from(new Set([...(card.brandExamples || []), ...unclaimedExistingBrands])),
      entryType: card.classCard ? "drug-class-card" : "drug",
      classCard: Boolean(card.classCard),
      isDrugClassCard: Boolean(card.classCard),
      classExampleNames: card.classCard ? Array.from(new Set(card.classExampleNames || [])) : [],
      classExampleKeys: card.classCard ? Array.from(new Set(card.classExampleKeys || [])) : [],
      tags: Array.from(new Set([...(existing.tags || []), ...(card.tags || [])])),
      adverseEffects: Array.isArray(card.adverseEffects) ? card.adverseEffects : [],
      contraindications: Array.isArray(card.contraindications) ? card.contraindications : [],
      nursingEssentials: Array.isArray(card.nursingEssentials) ? card.nursingEssentials : [],
      interactions: Array.isArray(card.interactions) ? card.interactions : [],
      keyLabs: Array.isArray(card.keyLabs) ? card.keyLabs : [],
      nclexTraps: Array.isArray(card.nclexTraps) ? card.nclexTraps : [],
      populationRisks: Array.isArray(card.populationRisks) ? card.populationRisks : [],
      templateKey: card.classCard ? "curated drug class card" : "curated full study card",
      confidenceTier: card.classCard ? "Curated drug class card" : "Curated full study card",
      expandedIndex: false,
      hidden: false,
      studentFacing: true,
      combinationProduct: card.combinationProduct === true || existing.combinationProduct === true,
      studentFacingCombinationCard: card.studentFacingCombinationCard === true || existing.studentFacingCombinationCard === true,
      deprecatedCombinationProduct: false,
      nclexEssential: true
    });
  });

  db.drugs = Array.from(map.values());
  db.pharmFrontierWave14CardiovascularRaasPatch = {
    version: "2026-07-16-cardiovascular-raas-causal-repair",
    promotedDrugCount: drugCards.length,
    pathwayCardCount: classCards.length,
    totalCardCount: cards.length
  };
  db.version = [db.version, "pharm-frontier-wave14-cardiovascular-raas"].filter(Boolean).join("+");
